const lines = [];
let line;
while ((line = readLine()) !== null) lines.push(line);
const tok = lines.join(' ').split(/\s+/).filter(s => s.length).map(Number);
const k = tok[0];
function extGcd(a, b) {
  if (b === 0) return [a, 1, 0];
  const [g, x1, y1] = extGcd(b, a % b);
  return [g, y1, x1 - Math.floor(a / b) * y1];
}
function inverse(a, m) {
  if (m === 1) return 0;
  const [, x] = extGcd(a % m, m);
  return ((x % m) + m) % m;
}
let x = 0, M = 1, answer = null;
for (let i = 0; i < k; i++) {
  const r = tok[1 + 2 * i], m = tok[2 + 2 * i];
  const g = extGcd(M, m)[0];
  const diff = (((r - x) % m) + m) % m;
  if (diff % g !== 0) { answer = -1; break; }
  const mg = m / g;
  const t = ((diff / g) % mg) * inverse((M / g) % mg, mg) % mg;
  x += M * t;
  M = (M / g) * m;
  x %= M;
}
console.log(String(answer !== null ? answer : x));

