import java.io.*;
import java.util.*;

public class Main {
    static long[] extGcd(long a, long b) {
        if (b == 0) return new long[]{a, 1, 0};
        long[] r = extGcd(b, a % b);
        return new long[]{r[0], r[2], r[1] - (a / b) * r[2]};
    }

    static long inverse(long a, long m) {
        if (m == 1) return 0;
        long x = extGcd(a % m, m)[1];
        return ((x % m) + m) % m;
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedInputStream(System.in));
        in.nextToken();
        int k = (int) in.nval;
        long x = 0, M = 1;
        boolean ok = true;
        for (int i = 0; i < k; i++) {
            in.nextToken();
            long r = (long) in.nval;
            in.nextToken();
            long m = (long) in.nval;
            if (!ok) continue;
            long g = extGcd(M, m)[0];
            long diff = ((r - x) % m + m) % m;
            if (diff % g != 0) { ok = false; continue; }
            long mg = m / g;
            long t = ((diff / g) % mg) * inverse((M / g) % mg, mg) % mg;
            x += M * t;
            M = M / g * m;
            x %= M;
        }
        System.out.println(ok ? x : -1);
    }
}

