#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

ll ext_gcd(ll a, ll b, ll& x, ll& y) {
    if (b == 0) { x = 1; y = 0; return a; }
    ll x1, y1;
    ll g = ext_gcd(b, a % b, x1, y1);
    x = y1;
    y = x1 - (a / b) * y1;
    return g;
}
ll inverse(ll a, ll m) {
    if (m == 1) return 0;
    ll x, y;
    ext_gcd(a % m, m, x, y);
    return ((x % m) + m) % m;
}
int main() {
    int k;
    scanf("%d", &k);
    ll x = 0, M = 1;
    bool ok = true;
    for (int i = 0; i < k; i++) {
        ll r, m;
        scanf("%lld %lld", &r, &m);
        if (!ok) continue;
        ll a, b;
        ll g = ext_gcd(M, m, a, b);
        ll diff = ((r - x) % m + m) % m;
        if (diff % g != 0) { ok = false; continue; }
        ll mg = m / g;
        ll t = ((diff / g) % mg) * inverse((M / g) % mg, mg) % mg;
        x += M * t;
        M = M / g * m;
        x %= M;
    }
    printf("%lld\n", ok ? x : -1LL);
    return 0;
}
